    if (!legal.length) return null;
    var P = HI.TRAINED.hard;
    var N = state.config.settleCards || 2;
    var need = state.config.winsNeeded;
    var rule = (E.DIFFICULTIES[state.config.difficulty] || {}).rule || 'none';
    var deckLen = state.deck.length;
    var unseen = E.getUnseenCards(state, pid);
    var unseenValues = new Array(unseen.length);
    for (var ui = 0; ui < unseen.length; ui++) unseenValues[ui] = unseen[ui].value;
    var ev = HI.makeEvaluator(unseenValues, N, 'hard', ZERO_RNG, true);
    var plans = buildHeuristicPlans(state, pid, HI, o.heuristicTop);
    if (!plans || !plans.length) return null;
