    var requiredGap = bestIsPass ? Math.max(Number(o.margin) || 0, 0.02) : o.margin;
    if (best !== 0 && allScored[best].score > allScored[0].score + requiredGap) {
      return { action: allScored[best].plan.actions[0], score: allScored[best].score, baseAction: baseAction, baseScore: allScored[0].score, reranked: true };
    }
